from pathlib import Path
from html import escape
p=Path(__file__).resolve().parents[1]
toronto={"city":"toronto","title":"Toronto","stats":"421 groups · 50 categories","hoods":['Kensington','The Junction','Leslieville','High Park'],"files":['kensington','junction','leslieville','high-park']}
vancouver={"city":"vancouver","title":"Vancouver","stats":"Clubs, groups & communities","hoods":['Kitsilano','Mount Pleasant','Commercial Drive','Stanley Park'],"files":['kitsilano','mount-pleasant','commercial-drive','stanley-park']}
categories=[('Social','15',['Social & Friend Clubs','Language Exchange','Pub Trivia Nights','Underground DJs & Dance','Supper Clubs & Dinner Clubs']),('Games & Learning','15',['Board Game Groups','Improv & Comedy','Book Clubs','Chess Clubs','Public Speaking']),('Community','22',['Newcomer & Community Resources','Vinyl Bars & Record Stores',"Men’s Groups",'Volunteering','Community Gardens']),('Sports & Outdoors','17',['Hiking & Outdoors','Run Clubs','Cycling Clubs','Climbing','Paddling & Sailing']),('Creative','15',['Writing Groups & Workshops','Music & Open Mics','Art & Drawing','Photography','Film Clubs']),('Mind & Body','14',['Dance Classes & Socials','Yoga & Movement','Meditation & Mindfulness','Philosophy Circles','Wellness & Recovery'])]
def directory():
 return '<div class="directory-grid">'+''.join(f'<section class="category"><h3>{escape(name)} <span>({n})</span></h3><ul>'+''.join(f'<li><a href="category-toronto.html">{escape(item)}</a></li>' for item in items)+'</ul><a class="more" href="category-toronto.html">view all →</a></section>' for name,n,items in categories)+'</div>'
def header(c):
 return f'<header class="site-header"><div class="container"><div class="header-top"><a class="wordmark" href="homepage-{c["city"]}.html">{c["city"]} community</a><span class="metadata">{c["stats"]}</span></div><nav class="nav"><a class="active" href="homepage-{c["city"]}.html">directory</a><a href="guide-toronto.html">new to {c["title"].lower()}</a><a href="#">add a group</a><a href="#">blog</a><a href="#">about</a></nav></div></header>'
def foot(c):return f'<div class="container"><img class="footer-art" src="../assets/{c["city"]}/skyline-strip.svg" alt=""/><footer class="footer">{c["city"]} community — local groups, made easier to find. • Illustration and content are implementation references.</footer></div>'
def shell(c,body,title):
 s=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} — {c['city']} community</title><link rel="stylesheet" href="../tokens/shared.css"><link rel="stylesheet" href="../tokens/{c['city']}.css"></head><body>{header(c)}<main class="container">{body}</main>{foot(c)}</body></html>'''
 return s
for c in [toronto,vancouver]:
 city=c['city']; art=f'../assets/{city}/hero-street.svg'
 hoods=''.join(f'<div class="neighbourhood"><img class="pixel-art" src="../assets/{city}/neighbourhoods/{file}.svg" alt="Pixel illustration of {escape(label)}"/><a href="#">{escape(label)} ↗</a></div>' for label,file in zip(c['hoods'],c['files']))
 sidebar=f'''<aside class="sidebar"><div class="sidebar-block"><span class="eyebrow">start here</span><h3>new to {city}?</h3><p>A short, practical guide to finding people and communities in the city.</p><a href="guide-toronto.html">read the guide →</a></div><div class="sidebar-block"><span class="eyebrow">reading list</span><h3>useful guides</h3><ul><li><a href="#">How to make friends in {c['title']}</a></li><li><a href="#">The best book clubs</a></li><li><a href="#">Things to do alone</a></li><li><a href="#">Writing groups</a></li></ul></div><div class="sidebar-block"><h3>the {city} roundup</h3><p>New groups and community picks, weekly.</p><form class="subscribe" onsubmit="event.preventDefault()"><input aria-label="Email" type="email" placeholder="your@email.com" required/><button>join</button></form></div></aside>'''
 body=f'''<section class="hero"><div><span class="eyebrow">a directory for getting out there</span><h1>find your people<br>in {city}.</h1><p>Find run clubs, book groups, maker spaces, neighbourhood meetups, and more. Real communities, all in one place.</p><form class="search" onsubmit="event.preventDefault()"><input aria-label="Search communities" placeholder="search groups: hiking, chess, book clubs…"><button>search</button></form><div class="popular">popular: <a href="#">run clubs</a> <a href="#">book clubs</a> <a href="#">supper clubs</a> <a href="#">hiking</a></div></div><div class="hero-art"><img class="pixel-art" src="{art}" alt="Minimal pixel-built {city} street scene"></div></section><section class="section home-content"><div><span class="eyebrow">the city index / 01</span><h2 class="section-title">browse the directory</h2>{directory()}</div>{sidebar}</section><section class="section"><span class="eyebrow">closer to home / 02</span><h2 class="section-title">explore by neighbourhood</h2><div class="neighbourhood-grid">{hoods}</div></section>'''
 (p/'mockups'/f'homepage-{city}.html').write_text(shell(c,body,'Homepage'))
# category and group are Toronto prototypes with illustrative group names
body='''<section class="section"><span class="eyebrow">directory / sports & outdoors</span><h1 style="font-size:clamp(38px,5vw,62px);letter-spacing:-.05em;margin:10px 0">run clubs in toronto</h1><p style="color:var(--muted);max-width:680px;line-height:1.6">Find casual social runs, community-led workouts and neighbourhood running groups. Sample content: replace with live listings.</p></section><section class="section detail-columns"><div><h2 class="section-title">explore groups</h2><ul class="result-list"><li><span class="tag">running · west end · sample listing</span><p><a href="group-toronto.html">West End Run Club →</a></p><p>Easy-paced social runs and weekend meetups. Details should come from a verified directory record.</p></li><li><span class="tag">running · downtown · sample listing</span><p><a href="group-toronto.html">Downtown Social Runs →</a></p><p>A second example to demonstrate list hierarchy and metadata.</p></li><li><span class="tag">running · east end · sample listing</span><p><a href="group-toronto.html">East Side Running Group →</a></p><p>A third example. Never ship unverified groups as real listings.</p></li></ul></div><aside class="sidebar"><div class="sidebar-block"><h3>browse nearby topics</h3><ul><li><a href="#">hiking & outdoors</a></li><li><a href="#">cycling groups</a></li><li><a href="#">climbing</a></li></ul></div><div class="sidebar-block"><h3>know a group?</h3><a href="#">suggest a listing →</a></div></aside></section>'''
(p/'mockups'/'category-toronto.html').write_text(shell(toronto,body,'Category page'))
body='''<section class="section"><a href="category-toronto.html">← back to run clubs</a><span class="eyebrow" style="display:block;margin-top:35px">community profile / sample content</span><h1 style="font-size:clamp(40px,5vw,68px);letter-spacing:-.05em;margin:12px 0">West End Run Club</h1><p style="font-size:19px;color:var(--muted)">A template for presenting a real group, not a verified listing.</p></section><section class="section detail-columns"><div><h2>about the group</h2><p style="line-height:1.7">This page demonstrates simple, readable group information. Actual description, location, time, links, contact details and verification status must come from your CMS or directory records.</p><h2>what to expect</h2><p style="line-height:1.7">Keep participation info, accessibility notes, costs and schedule easy to scan. Avoid invented reviews, attendance counts, or hours.</p></div><aside class="sidebar"><div class="sidebar-block"><h3>at a glance</h3><p>Area: <strong>sample / unverified</strong></p><p>Schedule: <strong>not supplied</strong></p><p>Cost: <strong>not supplied</strong></p></div><div class="sidebar-block"><h3>more like this</h3><a href="category-toronto.html">all run clubs →</a></div></aside></section>'''
(p/'mockups'/'group-toronto.html').write_text(shell(toronto,body,'Group page'))
body='''<section class="section article"><span class="eyebrow">guides / getting started</span><h1 style="font-size:clamp(40px,5.5vw,72px);letter-spacing:-.055em;line-height:1.05;margin:16px 0">new to toronto?<br>start here.</h1><p style="font-size:20px;color:var(--muted)">A practical guide to discovering people and places without turning community into another social feed.</p></section><section class="section article"><h2>start with something you already like</h2><p>Sports, books, games, making things, volunteering: shared activities make it easier to return and become a regular. Link readers directly to relevant, maintained directory categories.</p><p><a href="category-toronto.html">browse run clubs →</a> · <a href="#">browse book clubs →</a></p><h2>make it easy to go twice</h2><p>The first visit is an introduction. The second is often when a group starts to feel familiar. Keep advice concrete, local and connected to actual group listings.</p><h2>look beyond downtown</h2><p>Neighbourhood discovery belongs alongside interests, but never invent neighbourhood-specific group counts.</p></section>'''
(p/'mockups'/'guide-toronto.html').write_text(shell(toronto,body,'Guide page'))
print('Wrote HTML reference pages')
